SELECT id, user_id, goal_id, title, type, source_url, description, tags,
       created_at, updated_at
FROM learning_resource
WHERE user_id = #{userId}
AND type = #{type}
AND goal_id = #{goalId}
ORDER BY updated_at DESC, created_at DESC

SELECT id, user_id, goal_id, title, type, source_url, description, tags,
       created_at, updated_at
FROM learning_resource WHERE id = #{id}
